var taskList = this.workContext.getJobTaskList();
//print(taskList.length);
//print("-----------");
var ch = "";
if(taskList.length>0){
    for(i=0;i<taskList.length;i++){
        print(taskList[i].unit);
        unit = taskList[i].unit.substring(0,taskList[i].unit.indexOf("@"));
        identity = taskList[i].identity.substring(0,taskList[i].identity.indexOf("@"));
        ch = ch==="" ? unit+"-"+identity : ch+";"+unit+"-"+identity;
    }
}
